<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_moderation_assets() { if ( ! is_page_template( array( 'page-templates/account-settings.php', 'page-templates/member-profile.php', 'page-templates/social-feed.php', 'page-templates/communities.php', 'page-templates/messages.php' ) ) ) { return; } wp_enqueue_style( 'sd-moderation', SD_URI . '/assets/css/moderation.css', array( 'sd-style' ), SD_VERSION ); wp_enqueue_style( 'sd-privacy', SD_URI . '/assets/css/privacy.css', array( 'sd-style' ), SD_VERSION ); wp_enqueue_style( 'sd-moderation-responsive', SD_URI . '/assets/css/moderation-responsive.css', array( 'sd-moderation' ), SD_VERSION ); wp_enqueue_script( 'sd-reporting', SD_URI . '/assets/js/reporting.js', array(), SD_VERSION, true ); wp_enqueue_script( 'sd-blocking', SD_URI . '/assets/js/blocking.js', array(), SD_VERSION, true ); wp_localize_script( 'sd-reporting', 'sdSafety', array( 'restUrl' => esc_url_raw( rest_url( 'social-discovery/v1/' ) ), 'nonce' => wp_create_nonce( 'wp_rest' ) ) ); }
add_action( 'wp_enqueue_scripts', 'sd_moderation_assets' );
